      ))

    const confined = await harness({ config: { isolation: 'host' }, providers: { 'claude-code': PRODUCT_CAPABILITIES } })
    expect(() => confined.ctx.environmentRuns.checkImplementer({ kind: 'subagent', provider: 'claude-code' }, MODEL))
      .toThrow(new EnvironmentRunError(
